@import "tailwindcss";

:root {
  --background: #ffffff;
  --foreground: #171717;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
}

@media (prefers-color-scheme: dark) {
  :root {
    --background: #0a0a0a;
    --foreground: #ededed;
  }
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: Arial, Helvetica, sans-serif;
}

import type { Metadata } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import "./globals.css";

const geistSans = Geist({
  variable: "--font-geist-sans",
  subsets: ["latin"],
});

const geistMono = Geist_Mono({
  variable: "--font-geist-mono",
  subsets: ["latin"],
});

export const metadata: Metadata = {
  title: "EPL Digest | Premier League Rundown & Player Intel",
  description: "Live Premier League match results, standout player ratings, table shifts, and star player injury intel with personalized team and player tracking.",
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html
      lang="en"
      className={`${geistSans.variable} ${geistMono.variable} h-full antialiased dark`}
    >
      <body className="min-h-full flex flex-col bg-[#0a0a0c] text-neutral-100">{children}</body>
    </html>
  );
}

import { Suspense } from 'react';
import { getPremierLeagueRundown } from '@/lib/rundownService';
import { RundownDashboard } from '@/components/RundownDashboard';

async function DashboardContent() {
  const data = await getPremierLeagueRundown();
  return <RundownDashboard initialData={data} />;
}

export default function HomePage() {
  return (
    <Suspense
      fallback={
        <div className="min-h-screen bg-[#0a0a0c] flex items-center justify-center text-neutral-400">
          <div className="flex flex-col items-center gap-3">
            <div className="w-8 h-8 border-2 border-emerald-400 border-t-transparent rounded-full animate-spin" />
            <p className="text-sm font-medium">Loading Premier League Rundown...</p>
          </div>
        </div>
      }
    >
      <DashboardContent />
    </Suspense>
  );
}

import { NextResponse } from 'next/server';
import { getPremierLeagueRundown } from '@/lib/rundownService';

export async function GET() {
  try {
    const data = await getPremierLeagueRundown();
    return NextResponse.json(data);
  } catch (error) {
    console.error('API route error in /api/rundown:', error);
    return NextResponse.json({ error: 'Failed to retrieve rundown data' }, { status: 500 });
  }
}

'use client';

import React, { useState } from 'react';
import { Team, Player, FavoritesState } from '@/types';
import { X, Search, Star, Heart, Check, Trash2, Sparkles, Shield } from 'lucide-react';

interface FavoritesModalProps {
  isOpen: boolean;
  onClose: () => void;
  allTeams: Team[];
  allPlayers: Player[];
  favorites: FavoritesState;
  onUpdateFavorites: (favorites: FavoritesState) => void;
}

export function FavoritesModal({
  isOpen,
  onClose,
  allTeams,
  allPlayers,
  favorites,
  onUpdateFavorites,
}: FavoritesModalProps) {
  const [activeTab, setActiveTab] = useState<'teams' | 'players'>('teams');
  const [playerSearch, setPlayerSearch] = useState('');
  const [teamSearch, setTeamSearch] = useState('');
  const [selectedTeamFilter, setSelectedTeamFilter] = useState<number | 'all'>('all');
  const [onlyStarsFilter, setOnlyStarsFilter] = useState(false);

  if (!isOpen) return null;

  const toggleTeam = (teamId: number) => {
    const exists = favorites.teamIds.includes(teamId);
    const newTeamIds = exists
      ? favorites.teamIds.filter(id => id !== teamId)
      : [...favorites.teamIds, teamId];
    onUpdateFavorites({ ...favorites, teamIds: newTeamIds });
  };

  const togglePlayer = (playerId: number) => {
    const exists = favorites.playerIds.includes(playerId);
    const newPlayerIds = exists
      ? favorites.playerIds.filter(id => id !== playerId)
      : [...favorites.playerIds, playerId];
    onUpdateFavorites({ ...favorites, playerIds: newPlayerIds });
  };

  const selectBigSix = () => {
    // Man City, Arsenal, Liverpool, Chelsea, Man Utd, Spurs
    const bigSixShorts = ['MCI', 'ARS', 'LIV', 'CHE', 'MUN', 'TOT'];
    const bigSixIds = allTeams.filter(t => bigSixShorts.includes(t.shortName)).map(t => t.id);
    const combined = Array.from(new Set([...favorites.teamIds, ...bigSixIds]));
    onUpdateFavorites({ ...favorites, teamIds: combined });
  };

  const selectTopStars = () => {
    const starIds = allPlayers.filter(p => p.isStar).slice(0, 8).map(p => p.id);
    const combined = Array.from(new Set([...favorites.playerIds, ...starIds]));
    onUpdateFavorites({ ...favorites, playerIds: combined });
  };

  const clearAllFavorites = () => {
    onUpdateFavorites({ teamIds: [], playerIds: [] });
  };

  const filteredTeams = allTeams.filter(t =>
    t.name.toLowerCase().includes(teamSearch.toLowerCase()) ||
    t.shortName.toLowerCase().includes(teamSearch.toLowerCase())
  );

  const filteredPlayers = allPlayers.filter(p => {
    const matchesSearch =
      p.webName.toLowerCase().includes(playerSearch.toLowerCase()) ||
      p.firstName.toLowerCase().includes(playerSearch.toLowerCase()) ||
      p.secondName.toLowerCase().includes(playerSearch.toLowerCase()) ||
      p.teamName.toLowerCase().includes(playerSearch.toLowerCase());
    const matchesTeam = selectedTeamFilter === 'all' || p.teamId === selectedTeamFilter;
    const matchesStar = !onlyStarsFilter || p.isStar;
    return matchesSearch && matchesTeam && matchesStar;
  }).slice(0, 60);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
      <div 
        className="w-full max-w-4xl max-h-[90vh] bg-neutral-900 border border-neutral-800 rounded-2xl shadow-2xl flex flex-col overflow-hidden text-neutral-100 animate-in fade-in zoom-in-95 duration-200"
      >
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-neutral-800 bg-neutral-950/60">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-amber-400 to-amber-600 flex items-center justify-center text-neutral-950 shadow-lg shadow-amber-500/20">
              <Star className="w-5 h-5 fill-current" />
            </div>
            <div>
              <h2 className="text-xl font-bold tracking-tight">Personalize Favorites</h2>
              <p className="text-xs text-neutral-400">
                Choose your favorite teams and star players to customize your Premier League feed
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 rounded-xl text-neutral-400 hover:text-white hover:bg-neutral-800 transition"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Tab switcher & quick presets */}
        <div className="px-6 py-3 bg-neutral-900 border-b border-neutral-800 flex flex-wrap items-center justify-between gap-3">
          <div className="flex items-center bg-neutral-950 p-1 rounded-xl border border-neutral-800">
            <button
              onClick={() => setActiveTab('teams')}
              className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-sm font-medium transition ${
                activeTab === 'teams'
                  ? 'bg-neutral-800 text-white shadow-sm'
                  : 'text-neutral-400 hover:text-white'
              }`}
            >
              <Shield className="w-4 h-4" />
              Teams ({favorites.teamIds.length})
            </button>
            <button
              onClick={() => setActiveTab('players')}
              className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-sm font-medium transition ${
                activeTab === 'players'
                  ? 'bg-neutral-800 text-white shadow-sm'
                  : 'text-neutral-400 hover:text-white'
              }`}
            >
              <Heart className="w-4 h-4" />
              Players ({favorites.playerIds.length})
            </button>
          </div>

          <div className="flex items-center gap-2 text-xs">
            {activeTab === 'teams' ? (
              <button
                onClick={selectBigSix}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-neutral-800/80 hover:bg-neutral-700 text-neutral-300 hover:text-white border border-neutral-700/50 transition"
              >
                <Sparkles className="w-3.5 h-3.5 text-amber-400" />
                Select Big Six
              </button>
            ) : (
              <button
                onClick={selectTopStars}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-neutral-800/80 hover:bg-neutral-700 text-neutral-300 hover:text-white border border-neutral-700/50 transition"
              >
                <Sparkles className="w-3.5 h-3.5 text-amber-400" />
                Select Top Talismans
              </button>
            )}

            {(favorites.teamIds.length > 0 || favorites.playerIds.length > 0) && (
              <button
                onClick={clearAllFavorites}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-red-400 hover:text-red-300 hover:bg-red-500/10 border border-red-500/20 transition"
              >
                <Trash2 className="w-3.5 h-3.5" />
                Clear All
              </button>
            )}
          </div>
        </div>

        {/* Tab Content */}
        <div className="flex-1 overflow-y-auto p-6 space-y-4">
          {activeTab === 'teams' && (
            <div className="space-y-4">
              <div className="relative">
                <Search className="w-4 h-4 text-neutral-500 absolute left-3.5 top-1/2 -translate-y-1/2" />
                <input
                  type="text"
                  placeholder="Search clubs (e.g. Arsenal, Liverpool, City)..."
                  value={teamSearch}
                  onChange={(e) => setTeamSearch(e.target.value)}
                  className="w-full bg-neutral-950 border border-neutral-800 rounded-xl pl-10 pr-4 py-2 text-sm text-white placeholder-neutral-500 focus:outline-none focus:border-neutral-600"
                />
              </div>

              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3">
                {filteredTeams.map((team) => {
                  const isSelected = favorites.teamIds.includes(team.id);
                  return (
                    <button
                      key={team.id}
                      onClick={() => toggleTeam(team.id)}
                      className={`relative flex items-center gap-3 p-3 rounded-xl border text-left transition-all ${
                        isSelected
                          ? 'bg-neutral-800 border-amber-500/60 shadow-md shadow-amber-500/10 ring-1 ring-amber-500/50'
                          : 'bg-neutral-950/60 border-neutral-800/80 hover:border-neutral-700 hover:bg-neutral-800/40'
                      }`}
                    >
                      <div
                        className="w-9 h-9 rounded-lg flex items-center justify-center font-black text-xs text-white shadow"
                        style={{ backgroundColor: team.primaryColor }}
                      >
                        {team.shortName}
                      </div>

                      <div className="flex-1 min-w-0">
                        <div className="text-sm font-semibold truncate text-white">{team.name}</div>
                        <div className="text-[11px] text-neutral-400">{team.shortName}</div>
                      </div>

                      <div
                        className={`w-5 h-5 rounded-full flex items-center justify-center transition ${
                          isSelected
                            ? 'bg-amber-400 text-neutral-950'
                            : 'border border-neutral-700 text-transparent'
                        }`}
                      >
                        <Check className="w-3.5 h-3.5 stroke-[3]" />
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {activeTab === 'players' && (
            <div className="space-y-4">
              <div className="flex flex-col sm:flex-row gap-3">
                <div className="relative flex-1">
                  <Search className="w-4 h-4 text-neutral-500 absolute left-3.5 top-1/2 -translate-y-1/2" />
                  <input
                    type="text"
                    placeholder="Search players (e.g. Haaland, Saka, Salah, Palmer)..."
                    value={playerSearch}
                    onChange={(e) => setPlayerSearch(e.target.value)}
                    className="w-full bg-neutral-950 border border-neutral-800 rounded-xl pl-10 pr-4 py-2 text-sm text-white placeholder-neutral-500 focus:outline-none focus:border-neutral-600"
                  />
                </div>

                <div className="flex items-center gap-2">
                  <select
                    value={selectedTeamFilter}
                    onChange={(e) => setSelectedTeamFilter(e.target.value === 'all' ? 'all' : Number(e.target.value))}
                    className="bg-neutral-950 border border-neutral-800 rounded-xl px-3 py-2 text-xs text-neutral-300 focus:outline-none focus:border-neutral-600"
                  >
                    <option value="all">All Teams</option>
                    {allTeams.map(t => (
                      <option key={t.id} value={t.id}>{t.name}</option>
                    ))}
                  </select>

                  <button
                    onClick={() => setOnlyStarsFilter(!onlyStarsFilter)}
                    className={`flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-medium border transition ${
                      onlyStarsFilter
                        ? 'bg-amber-500/20 text-amber-300 border-amber-500/50'
                        : 'bg-neutral-950 text-neutral-400 border-neutral-800 hover:text-white'
                    }`}
                  >
                    <Star className="w-3.5 h-3.5 fill-current" />
                    Star Players
                  </button>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3">
                {filteredPlayers.map((player) => {
                  const isSelected = favorites.playerIds.includes(player.id);
                  return (
                    <div
                      key={player.id}
                      onClick={() => togglePlayer(player.id)}
                      className={`cursor-pointer relative flex items-center justify-between p-3 rounded-xl border transition-all ${
                        isSelected
                          ? 'bg-neutral-800 border-amber-500/60 shadow-md shadow-amber-500/10 ring-1 ring-amber-500/50'
                          : 'bg-neutral-950/60 border-neutral-800/80 hover:border-neutral-700 hover:bg-neutral-800/40'
                      }`}
                    >
                      <div className="flex items-center gap-3 min-w-0">
                        <div className="w-9 h-9 rounded-full bg-neutral-800 border border-neutral-700 flex items-center justify-center font-bold text-xs text-neutral-200">
                          {player.position}
                        </div>
                        <div className="min-w-0">
                          <div className="flex items-center gap-1.5">
                            <span className="text-sm font-bold text-white truncate">{player.webName}</span>
                            {player.isStar && (
                              <Star className="w-3 h-3 text-amber-400 fill-amber-400 shrink-0" />
                            )}
                          </div>
                          <div className="text-xs text-neutral-400 flex items-center gap-2">
                            <span>{player.teamShortName}</span>
                            <span>•</span>
                            <span>{player.goals}G {player.assists}A</span>
                            <span>•</span>
                            <span className="text-amber-400/90 font-medium">{player.totalPoints} pts</span>
                          </div>
                        </div>
                      </div>

                      <button
                        type="button"
                        className={`p-2 rounded-lg transition ${
                          isSelected
                            ? 'text-amber-400 bg-amber-400/10'
                            : 'text-neutral-500 hover:text-neutral-300'
                        }`}
                      >
                        <Heart className={`w-4 h-4 ${isSelected ? 'fill-amber-400' : ''}`} />
                      </button>
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-neutral-800 bg-neutral-950/80 flex items-center justify-between">
          <div className="text-xs text-neutral-400">
            Selected: <span className="text-white font-medium">{favorites.teamIds.length} Teams</span>,{' '}
            <span className="text-white font-medium">{favorites.playerIds.length} Players</span>
          </div>
          <button
            onClick={onClose}
            className="px-5 py-2 bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-400 hover:to-teal-400 text-neutral-950 font-bold rounded-xl text-sm transition shadow-lg shadow-emerald-500/20"
          >
            Done & Apply
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

import React from 'react';
import { Star, RefreshCw, Filter, Sparkles, Trophy } from 'lucide-react';
import { FavoritesState } from '@/types';

interface HeaderProps {
  currentGameweek: number;
  season: string;
  favorites: FavoritesState;
  onOpenFavorites: () => void;
  myFeedOnly: boolean;
  onToggleMyFeed: () => void;
  onRefresh: () => void;
  isRefreshing: boolean;
  activeTab: 'all' | 'matches' | 'performers' | 'table' | 'news';
  onChangeTab: (tab: 'all' | 'matches' | 'performers' | 'table' | 'news') => void;
}

export function Header({
  currentGameweek,
  season,
  favorites,
  onOpenFavorites,
  myFeedOnly,
  onToggleMyFeed,
  onRefresh,
  isRefreshing,
  activeTab,
  onChangeTab,
}: HeaderProps) {
  const totalFavoritesCount = favorites.teamIds.length + favorites.playerIds.length;

  return (
    <header className="sticky top-0 z-40 bg-neutral-950/85 backdrop-blur-md border-b border-neutral-800/80">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Top Navbar */}
        <div className="flex items-center justify-between h-16 gap-4">
          {/* Brand */}
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-purple-700 via-indigo-600 to-emerald-400 p-0.5 shadow-lg shadow-purple-500/10">
              <div className="w-full h-full bg-neutral-950 rounded-[10px] flex items-center justify-center">
                <Trophy className="w-5 h-5 text-emerald-400" />
              </div>
            </div>

            <div>
              <div className="flex items-center gap-2">
                <span className="font-black text-xl tracking-tight text-white">EPL Digest</span>
                <span className="px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider rounded-md bg-emerald-500/15 text-emerald-400 border border-emerald-500/30">
                  GW {currentGameweek}
                </span>
              </div>
              <p className="text-[11px] text-neutral-400 hidden sm:block">
                Premier League Rundown & Player Intel • {season}
              </p>
            </div>
          </div>

          {/* Action buttons */}
          <div className="flex items-center gap-2 sm:gap-3">
            {/* My Feed Only Toggle */}
            <button
              onClick={onToggleMyFeed}
              className={`flex items-center gap-2 px-3.5 py-1.5 rounded-xl text-xs font-semibold border transition-all ${
                myFeedOnly
                  ? 'bg-amber-500/20 text-amber-300 border-amber-500/50 shadow-sm shadow-amber-500/20'
                  : 'bg-neutral-900 text-neutral-400 border-neutral-800 hover:text-white hover:bg-neutral-800'
              }`}
              title="Filter rundown to show only your favorite teams and players"
            >
              <Filter className={`w-3.5 h-3.5 ${myFeedOnly ? 'text-amber-400' : ''}`} />
              <span className="hidden sm:inline">My Feed Only</span>
              <span className="sm:hidden">My Feed</span>
              {myFeedOnly && (
                <span className="w-1.5 h-1.5 rounded-full bg-amber-400 animate-pulse" />
              )}
            </button>

            {/* Manage Favorites Button */}
            <button
              onClick={onOpenFavorites}
              className="flex items-center gap-2 px-3.5 py-1.5 rounded-xl text-xs font-semibold bg-neutral-900 border border-neutral-800 hover:border-neutral-700 text-neutral-200 hover:text-white transition"
            >
              <Star className="w-3.5 h-3.5 text-amber-400 fill-amber-400" />
              <span>Favorites</span>
              {totalFavoritesCount > 0 ? (
                <span className="px-1.5 py-0.2 text-[10px] rounded-full bg-amber-400 text-neutral-950 font-bold">
                  {totalFavoritesCount}
                </span>
              ) : (
                <span className="text-[10px] text-neutral-500 hidden md:inline">Setup</span>
              )}
            </button>

            {/* Refresh Button */}
            <button
              onClick={onRefresh}
              disabled={isRefreshing}
              className="p-2 rounded-xl bg-neutral-900 border border-neutral-800 hover:border-neutral-700 text-neutral-400 hover:text-white transition disabled:opacity-50"
              title="Refresh live match data and news"
            >
              <RefreshCw className={`w-4 h-4 ${isRefreshing ? 'animate-spin text-emerald-400' : ''}`} />
            </button>
          </div>
        </div>

        {/* View Tabs */}
        <div className="flex items-center gap-1 overflow-x-auto py-2 border-t border-neutral-900 scrollbar-none text-xs">
          {[
            { id: 'all', label: 'Full Rundown', icon: Sparkles },
            { id: 'matches', label: 'Match Results', icon: Trophy },
            { id: 'performers', label: 'Star Performers', icon: Star },
            { id: 'table', label: 'League Table & Movers', icon: Trophy },
            { id: 'news', label: 'Injuries & News', icon: Filter },
          ].map((tab) => {
            const Icon = tab.icon;
            const isActive = activeTab === tab.id;
            return (
              <button
                key={tab.id}
                onClick={() => onChangeTab(tab.id as HeaderProps['activeTab'])}
                className={`flex items-center gap-1.5 px-3.5 py-1.5 rounded-lg font-medium whitespace-nowrap transition ${
                  isActive
                    ? 'bg-neutral-800 text-white shadow-sm ring-1 ring-neutral-700'
                    : 'text-neutral-400 hover:text-neutral-200 hover:bg-neutral-900'
                }`}
              >
                <Icon className={`w-3.5 h-3.5 ${isActive ? 'text-emerald-400' : 'text-neutral-500'}`} />
                {tab.label}
              </button>
            );
          })}
        </div>
      </div>
    </header>
  );
}

'use client';

import React, { useState } from 'react';
import { LeagueTableEntry, FavoritesState } from '@/types';
import { Trophy, ArrowUp, ArrowDown, Minus, Star, TrendingUp } from 'lucide-react';

interface LeagueTableViewProps {
  table: LeagueTableEntry[];
  favorites: FavoritesState;
  onOpenFavorites: () => void;
  myFeedOnly: boolean;
}

export function LeagueTableView({
  table,
  favorites,
  onOpenFavorites,
  myFeedOnly,
}: LeagueTableViewProps) {
  const [showMoversOnly, setShowMoversOnly] = useState(false);

  const filteredTable = table.filter(entry => {
    if (showMoversOnly && entry.change === 0) return false;
    if (!myFeedOnly) return true;
    if (favorites.teamIds.length === 0) return true;
    return favorites.teamIds.includes(entry.team.id);
  });

  return (
    <div className="space-y-4">
      {/* Header & Controls */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 bg-neutral-900/60 border border-neutral-800 rounded-xl p-4">
        <div>
          <h2 className="text-lg font-bold text-white flex items-center gap-2">
            <Trophy className="w-5 h-5 text-amber-400" />
            League Table & Position Shifts
          </h2>
          <p className="text-xs text-neutral-400">
            Current standings, European qualification zones, relegation battle, and Gameweek table shifts
          </p>
        </div>

        <div className="flex items-center gap-2 self-start sm:self-auto">
          <button
            onClick={() => setShowMoversOnly(!showMoversOnly)}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold border transition ${
              showMoversOnly
                ? 'bg-emerald-500/20 text-emerald-300 border-emerald-500/50 shadow-sm'
                : 'bg-neutral-950 text-neutral-400 border-neutral-800 hover:text-white'
            }`}
          >
            <TrendingUp className="w-3.5 h-3.5" />
            <span>Table Movers Only ({table.filter(t => t.change !== 0).length})</span>
          </button>
        </div>
      </div>

      {/* Table Container */}
      <div className="overflow-x-auto rounded-2xl border border-neutral-800 bg-neutral-900/60 shadow-xl">
        <table className="w-full text-left text-xs whitespace-nowrap">
          <thead>
            <tr className="border-b border-neutral-800 bg-neutral-950/80 text-neutral-400 font-semibold uppercase tracking-wider text-[11px]">
              <th className="py-3.5 pl-4 pr-2 w-12 text-center">Pos</th>
              <th className="py-3.5 px-2 w-16 text-center">Shift</th>
              <th className="py-3.5 px-3">Club</th>
              <th className="py-3.5 px-2.5 text-center">Pl</th>
              <th className="py-3.5 px-2 text-center hidden sm:table-cell">W</th>
              <th className="py-3.5 px-2 text-center hidden sm:table-cell">D</th>
              <th className="py-3.5 px-2 text-center hidden sm:table-cell">L</th>
              <th className="py-3.5 px-2 text-center hidden md:table-cell">GF</th>
              <th className="py-3.5 px-2 text-center hidden md:table-cell">GA</th>
              <th className="py-3.5 px-2.5 text-center">GD</th>
              <th className="py-3.5 px-3 text-center font-bold text-white">Pts</th>
              <th className="py-3.5 pl-2 pr-4 text-center hidden lg:table-cell">Last 5 Form</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-neutral-800/60">
            {filteredTable.map((row) => {
              const isFavorite = favorites.teamIds.includes(row.team.id);

              // Qualification zone styles
              let zoneBorderColor = 'border-l-transparent';
              if (row.rank <= 4) zoneBorderColor = 'border-l-blue-500'; // Champions League
              else if (row.rank === 5) zoneBorderColor = 'border-l-orange-500'; // Europa League
              else if (row.rank === 6) zoneBorderColor = 'border-l-emerald-500'; // Conference League
              else if (row.rank >= 18) zoneBorderColor = 'border-l-rose-500'; // Relegation

              return (
                <tr
                  key={row.team.id}
                  className={`border-l-4 transition-colors ${zoneBorderColor} ${
                    isFavorite
                      ? 'bg-amber-500/10 hover:bg-amber-500/15 ring-1 ring-amber-500/30'
                      : 'hover:bg-neutral-800/40'
                  }`}
                >
                  {/* Position */}
                  <td className="py-3 pl-4 pr-2 text-center font-bold text-neutral-300">
                    <span
                      className={`inline-flex items-center justify-center w-6 h-6 rounded-md ${
                        row.rank === 1
                          ? 'bg-amber-400 text-neutral-950 font-black shadow-sm'
                          : row.rank <= 4
                          ? 'bg-blue-500/20 text-blue-300'
                          : row.rank >= 18
                          ? 'bg-rose-500/20 text-rose-300'
                          : 'text-neutral-400'
                      }`}
                    >
                      {row.rank}
                    </span>
                  </td>

                  {/* Movers Change indicator */}
                  <td className="py-3 px-2 text-center">
                    {row.change > 0 ? (
                      <span className="inline-flex items-center gap-0.5 px-1.5 py-0.5 rounded bg-emerald-500/15 text-emerald-400 font-bold text-[10px]">
                        <ArrowUp className="w-3 h-3 stroke-[2.5]" />
                        +{row.change}
                      </span>
                    ) : row.change < 0 ? (
                      <span className="inline-flex items-center gap-0.5 px-1.5 py-0.5 rounded bg-rose-500/15 text-rose-400 font-bold text-[10px]">
                        <ArrowDown className="w-3 h-3 stroke-[2.5]" />
                        {row.change}
                      </span>
                    ) : (
                      <span className="inline-flex items-center text-neutral-600 text-[11px]">
                        <Minus className="w-3 h-3" />
                      </span>
                    )}
                  </td>

                  {/* Club Details */}
                  <td className="py-3 px-3">
                    <div className="flex items-center gap-2.5">
                      <div
                        className="w-7 h-7 rounded-lg flex items-center justify-center font-black text-[10px] text-white shadow-sm shrink-0 border border-white/10"
                        style={{ backgroundColor: row.team.primaryColor }}
                      >
                        {row.team.shortName}
                      </div>

                      <div className="flex items-center gap-1.5">
                        <span className={`font-semibold ${isFavorite ? 'text-amber-300 font-bold' : 'text-white'}`}>
                          {row.team.name}
                        </span>
                        {isFavorite && (
                          <Star className="w-3.5 h-3.5 text-amber-400 fill-amber-400 shrink-0" />
                        )}
                      </div>
                    </div>
                  </td>

                  {/* Match record */}
                  <td className="py-3 px-2.5 text-center font-medium text-neutral-300">{row.played}</td>
                  <td className="py-3 px-2 text-center text-neutral-400 hidden sm:table-cell">{row.won}</td>
                  <td className="py-3 px-2 text-center text-neutral-400 hidden sm:table-cell">{row.drawn}</td>
                  <td className="py-3 px-2 text-center text-neutral-400 hidden sm:table-cell">{row.lost}</td>
                  <td className="py-3 px-2 text-center text-neutral-400 hidden md:table-cell">{row.gf}</td>
                  <td className="py-3 px-2 text-center text-neutral-400 hidden md:table-cell">{row.ga}</td>

                  {/* Goal Difference */}
                  <td className="py-3 px-2.5 text-center font-medium">
                    <span className={row.gd > 0 ? 'text-emerald-400' : row.gd < 0 ? 'text-rose-400' : 'text-neutral-400'}>
                      {row.gd > 0 ? `+${row.gd}` : row.gd}
                    </span>
                  </td>

                  {/* Points */}
                  <td className="py-3 px-3 text-center">
                    <span className="font-black text-sm text-white px-2 py-0.5 rounded bg-neutral-950/70 border border-neutral-800">
                      {row.points}
                    </span>
                  </td>

                  {/* Form */}
                  <td className="py-3 pl-2 pr-4 text-center hidden lg:table-cell">
                    <div className="flex items-center justify-center gap-1">
                      {row.form.map((res, i) => (
                        <span
                          key={i}
                          className={`w-5 h-5 rounded-md flex items-center justify-center text-[10px] font-black ${
                            res === 'W'
                              ? 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/30'
                              : res === 'D'
                              ? 'bg-neutral-700/50 text-neutral-300 border border-neutral-700'
                              : 'bg-rose-500/20 text-rose-400 border border-rose-500/30'
                          }`}
                        >
                          {res}
                        </span>
                      ))}
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>

        {/* Legend */}
        <div className="px-4 py-3 bg-neutral-950/80 border-t border-neutral-800 flex flex-wrap items-center justify-between gap-3 text-[11px] text-neutral-400">
          <div className="flex flex-wrap items-center gap-4">
            <span className="flex items-center gap-1.5">
              <span className="w-2.5 h-2.5 rounded-sm bg-blue-500" />
              Champions League (1-4)
            </span>
            <span className="flex items-center gap-1.5">
              <span className="w-2.5 h-2.5 rounded-sm bg-orange-500" />
              Europa League (5)
            </span>
            <span className="flex items-center gap-1.5">
              <span className="w-2.5 h-2.5 rounded-sm bg-emerald-500" />
              Conference League (6)
            </span>
            <span className="flex items-center gap-1.5">
              <span className="w-2.5 h-2.5 rounded-sm bg-rose-500" />
              Relegation Zone (18-20)
            </span>
          </div>

          <div className="flex items-center gap-2">
            <Star className="w-3.5 h-3.5 text-amber-400 fill-amber-400" />
            <span>Highlighted = Tracked Clubs</span>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { MatchResult, FavoritesState } from '@/types';
import { Trophy, Calendar, Star, Clock, Sparkles } from 'lucide-react';

interface MatchResultsViewProps {
  recentMatches: MatchResult[];
  upcomingMatches: MatchResult[];
  favorites: FavoritesState;
  onOpenFavorites: () => void;
  myFeedOnly: boolean;
}

export function MatchResultsView({
  recentMatches,
  upcomingMatches,
  favorites,
  onOpenFavorites,
  myFeedOnly,
}: MatchResultsViewProps) {
  const [activeSubTab, setActiveSubTab] = useState<'recent' | 'upcoming'>('recent');

  const matchesToFilter = activeSubTab === 'recent' ? recentMatches : upcomingMatches;

  const filteredMatches = matchesToFilter.filter(match => {
    if (!myFeedOnly) return true;
    if (favorites.teamIds.length === 0) return true;
    return favorites.teamIds.includes(match.homeTeam.id) || favorites.teamIds.includes(match.awayTeam.id);
  });

  const formatDate = (isoStr: string) => {
    try {
      const d = new Date(isoStr);
      return d.toLocaleDateString('en-GB', {
        weekday: 'short',
        day: 'numeric',
        month: 'short',
        hour: '2-digit',
        minute: '2-digit',
      });
    } catch {
      return isoStr;
    }
  };

  return (
    <div className="space-y-4">
      {/* Section Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 bg-neutral-900/60 border border-neutral-800 rounded-xl p-4">
        <div>
          <h2 className="text-lg font-bold text-white flex items-center gap-2">
            <Trophy className="w-5 h-5 text-emerald-400" />
            Match Results & Fixtures
          </h2>
          <p className="text-xs text-neutral-400">
            Official scores, matchday highlights, scorers, and key contributors
          </p>
        </div>

        {/* Sub-tab: Recent Results vs Upcoming Fixtures */}
        <div className="flex items-center bg-neutral-950 p-1 rounded-xl border border-neutral-800 self-start sm:self-auto">
          <button
            onClick={() => setActiveSubTab('recent')}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold transition ${
              activeSubTab === 'recent'
                ? 'bg-neutral-800 text-white shadow-sm'
                : 'text-neutral-400 hover:text-white'
            }`}
          >
            <Clock className="w-3.5 h-3.5" />
            Completed Results ({recentMatches.length})
          </button>
          <button
            onClick={() => setActiveSubTab('upcoming')}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold transition ${
              activeSubTab === 'upcoming'
                ? 'bg-neutral-800 text-white shadow-sm'
                : 'text-neutral-400 hover:text-white'
            }`}
          >
            <Calendar className="w-3.5 h-3.5" />
            Upcoming Next GW ({upcomingMatches.length})
          </button>
        </div>
      </div>

      {/* Match Cards Grid */}
      {filteredMatches.length === 0 ? (
        <div className="bg-neutral-900/40 border border-dashed border-neutral-800 rounded-2xl p-8 text-center space-y-3">
          <Star className="w-8 h-8 text-amber-400/50 mx-auto" />
          <h3 className="text-base font-semibold text-white">No matches for current filter</h3>
          <p className="text-xs text-neutral-400 max-w-sm mx-auto">
            None of your favorite teams have matches under the current filter. Try adding more clubs or turning off "My Feed Only".
          </p>
          <button
            onClick={onOpenFavorites}
            className="px-4 py-2 bg-neutral-800 hover:bg-neutral-700 text-amber-300 rounded-xl text-xs font-semibold transition"
          >
            Configure Favorite Clubs
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {filteredMatches.map(match => {
            const isHomeFavorite = favorites.teamIds.includes(match.homeTeam.id);
            const isAwayFavorite = favorites.teamIds.includes(match.awayTeam.id);
            const hasFavorite = isHomeFavorite || isAwayFavorite;

            return (
              <div
                key={match.id}
                className={`relative overflow-hidden rounded-2xl bg-neutral-900/80 border transition-all ${
                  hasFavorite
                    ? 'border-amber-500/40 shadow-lg shadow-amber-500/5 bg-gradient-to-b from-neutral-900 to-neutral-950'
                    : 'border-neutral-800/80 hover:border-neutral-700'
                }`}
              >
                {/* Favorite badge ribbon */}
                {hasFavorite && (
                  <div className="absolute top-2.5 right-3 flex items-center gap-1 px-2 py-0.5 rounded-full bg-amber-500/15 border border-amber-500/30 text-amber-400 text-[10px] font-bold">
                    <Star className="w-3 h-3 fill-amber-400" />
                    Tracked Club
                  </div>
                )}

                {/* Match Header */}
                <div className="px-5 py-3 border-b border-neutral-800/60 bg-neutral-950/40 flex items-center justify-between text-xs text-neutral-400">
                  <span className="flex items-center gap-1.5 font-medium">
                    <Calendar className="w-3.5 h-3.5 text-neutral-500" />
                    {formatDate(match.kickoffTime)}
                  </span>
                  <span className="px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider bg-neutral-800 text-neutral-300">
                    {match.finished ? 'Full Time' : `GW ${match.event}`}
                  </span>
                </div>

                {/* Teams & Scoreboard */}
                <div className="p-5">
                  <div className="flex items-center justify-between gap-4">
                    {/* Home Team */}
                    <div className="flex-1 flex flex-col items-center sm:items-start text-center sm:text-left gap-2 min-w-0">
                      <div className="flex items-center gap-2">
                        <div
                          className="w-10 h-10 rounded-xl flex items-center justify-center font-black text-sm text-white shadow-md border border-white/10 shrink-0"
                          style={{ backgroundColor: match.homeTeam.primaryColor }}
                        >
                          {match.homeTeam.shortName}
                        </div>
                        <div className="min-w-0">
                          <div className="text-sm font-bold text-white truncate flex items-center gap-1">
                            {match.homeTeam.name}
                            {isHomeFavorite && <Star className="w-3 h-3 text-amber-400 fill-amber-400" />}
                          </div>
                          <div className="text-[11px] text-neutral-400">{match.homeTeam.shortName}</div>
                        </div>
                      </div>
                    </div>

                    {/* Score or VS */}
                    <div className="shrink-0 flex flex-col items-center justify-center px-4 py-2 bg-neutral-950/80 rounded-xl border border-neutral-800 min-w-[72px]">
                      {match.finished ? (
                        <div className="text-2xl font-black text-white tracking-wider flex items-center gap-2">
                          <span>{match.homeScore}</span>
                          <span className="text-neutral-500 font-light">-</span>
                          <span>{match.awayScore}</span>
                        </div>
                      ) : (
                        <div className="text-sm font-bold text-neutral-400 tracking-widest">
                          VS
                        </div>
                      )}
                    </div>

                    {/* Away Team */}
                    <div className="flex-1 flex flex-col items-center sm:items-end text-center sm:text-right gap-2 min-w-0">
                      <div className="flex items-center justify-end gap-2">
                        <div className="min-w-0">
                          <div className="text-sm font-bold text-white truncate flex items-center justify-end gap-1">
                            {isAwayFavorite && <Star className="w-3 h-3 text-amber-400 fill-amber-400" />}
                            {match.awayTeam.name}
                          </div>
                          <div className="text-[11px] text-neutral-400">{match.awayTeam.shortName}</div>
                        </div>
                        <div
                          className="w-10 h-10 rounded-xl flex items-center justify-center font-black text-sm text-white shadow-md border border-white/10 shrink-0"
                          style={{ backgroundColor: match.awayTeam.primaryColor }}
                        >
                          {match.awayTeam.shortName}
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* Scorers & Assists Breakdown */}
                  {match.finished && (
                    <div className="mt-4 pt-4 border-t border-neutral-800/60 grid grid-cols-2 gap-4 text-xs">
                      {/* Home events */}
                      <div className="space-y-1">
                        {match.homeScorers.length > 0 ? (
                          match.homeScorers.map((s, idx) => (
                            <div key={idx} className="flex items-center gap-1.5 text-neutral-300 font-medium truncate">
                              <span>⚽</span>
                              <span className="truncate">{s.name} {s.count > 1 ? `(x${s.count})` : ''}</span>
                            </div>
                          ))
                        ) : (
                          <span className="text-[11px] text-neutral-500 italic">No goals</span>
                        )}

                        {match.homeAssists.map((a, idx) => (
                          <div key={idx} className="flex items-center gap-1.5 text-neutral-400 text-[11px] truncate">
                            <span>🎯</span>
                            <span className="truncate">{a.name}</span>
                          </div>
                        ))}
                      </div>

                      {/* Away events */}
                      <div className="space-y-1 text-right">
                        {match.awayScorers.length > 0 ? (
                          match.awayScorers.map((s, idx) => (
                            <div key={idx} className="flex items-center justify-end gap-1.5 text-neutral-300 font-medium truncate">
                              <span className="truncate">{s.name} {s.count > 1 ? `(x${s.count})` : ''}</span>
                              <span>⚽</span>
                            </div>
                          ))
                        ) : (
                          <span className="text-[11px] text-neutral-500 italic">No goals</span>
                        )}

                        {match.awayAssists.map((a, idx) => (
                          <div key={idx} className="flex items-center justify-end gap-1.5 text-neutral-400 text-[11px] truncate">
                            <span className="truncate">{a.name}</span>
                            <span>🎯</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}

                  {/* Match MVP Badge */}
                  {match.mvp && (
                    <div className="mt-3 pt-3 border-t border-neutral-800/40 flex items-center justify-between text-[11px] bg-neutral-950/40 -mx-5 -mb-5 px-5 py-2.5">
                      <span className="flex items-center gap-1.5 text-neutral-400 font-medium">
                        <Sparkles className="w-3.5 h-3.5 text-amber-400" />
                        Match MVP: <span className="text-white font-bold">{match.mvp.name} ({match.mvp.team})</span>
                      </span>
                      <span className="px-2 py-0.5 rounded bg-emerald-500/10 text-emerald-400 font-bold border border-emerald-500/20">
                        {match.mvp.points} Pts
                      </span>
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

'use client';

import React from 'react';
import { RundownData, FavoritesState } from '@/types';
import { TrendingUp, Flame, ShieldAlert, Award, Star, ArrowUpRight, ArrowDownRight } from 'lucide-react';

interface OverviewHeroProps {
  data: RundownData;
  favorites: FavoritesState;
  onOpenFavorites: () => void;
  myFeedOnly: boolean;
}

export function OverviewHero({
  data,
  favorites,
  onOpenFavorites,
  myFeedOnly,
}: OverviewHeroProps) {
  const leader = data.table[0];

  // Find biggest mover up
  const biggestMoverUp = [...data.table]
    .filter(t => t.change > 0)
    .sort((a, b) => b.change - a.change)[0];

  // Find biggest mover down
  const biggestMoverDown = [...data.table]
    .filter(t => t.change < 0)
    .sort((a, b) => a.change - b.change)[0];

  // Top performer of GW
  const topPerformer = data.topPerformers[0];

  // Star injury count
  const starInjuriesCount = data.injuryNews.filter(n => n.isStarPlayer).length;

  // Selected favorites
  const favoriteTeams = data.allTeams.filter(t => favorites.teamIds.includes(t.id));
  const favoritePlayers = data.allPlayers.filter(p => favorites.playerIds.includes(p.id));

  return (
    <div className="space-y-4">
      {/* Top Banner Card */}
      <div className="relative overflow-hidden rounded-2xl bg-gradient-to-br from-neutral-900 via-neutral-900/90 to-neutral-950 border border-neutral-800 p-6 shadow-xl">
        {/* Background glow effects */}
        <div className="absolute -top-24 -right-24 w-72 h-72 bg-emerald-500/10 rounded-full blur-3xl pointer-events-none" />
        <div className="absolute -bottom-24 -left-24 w-72 h-72 bg-purple-500/10 rounded-full blur-3xl pointer-events-none" />

        <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div className="space-y-2 max-w-2xl">
            <div className="inline-flex items-center gap-2 px-2.5 py-1 rounded-full bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 text-xs font-semibold">
              <span className="w-2 h-2 rounded-full bg-emerald-400 animate-ping" />
              Gameweek {data.currentGameweek} Rundown
            </div>

            <h1 className="text-2xl sm:text-3xl font-black tracking-tight text-white">
              Premier League Matchday Digest
            </h1>

            <p className="text-sm text-neutral-400 leading-relaxed">
              {myFeedOnly ? (
                <span className="text-amber-400 font-medium">
                  Showing your personalized feed for {favoriteTeams.length} favorite club{favoriteTeams.length !== 1 ? 's' : ''} and {favoritePlayers.length} tracked player{favoritePlayers.length !== 1 ? 's' : ''}.
                </span>
              ) : (
                <span>
                  Comprehensive analysis covering recent results, player ratings, standing shifts, and injury intel across all 20 clubs.
                </span>
              )}
            </p>
          </div>

          {/* Quick Favorite Clubs Bar */}
          <div className="flex flex-col gap-2 shrink-0 bg-neutral-950/60 border border-neutral-800/80 rounded-xl p-3 min-w-[240px]">
            <div className="flex items-center justify-between text-xs">
              <span className="text-neutral-400 font-medium flex items-center gap-1.5">
                <Star className="w-3.5 h-3.5 text-amber-400 fill-amber-400" />
                Tracked Clubs
              </span>
              <button
                onClick={onOpenFavorites}
                className="text-amber-400 hover:underline text-[11px]"
              >
                {favoriteTeams.length > 0 ? 'Edit' : '+ Add Clubs'}
              </button>
            </div>

            {favoriteTeams.length > 0 ? (
              <div className="flex flex-wrap gap-1.5 mt-1">
                {favoriteTeams.map(team => (
                  <span
                    key={team.id}
                    className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-bold text-white shadow-sm border border-white/10"
                    style={{ backgroundColor: team.primaryColor }}
                  >
                    {team.shortName}
                  </span>
                ))}
              </div>
            ) : (
              <p className="text-xs text-neutral-500 italic mt-1">
                No clubs selected yet. Click to pick your favorites!
              </p>
            )}
          </div>
        </div>

        {/* 4 Quick Stat Metric Tiles */}
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 mt-6 pt-6 border-t border-neutral-800/80">
          {/* Tile 1: League Leader */}
          <div className="bg-neutral-950/50 border border-neutral-800/60 rounded-xl p-3.5 space-y-1">
            <div className="flex items-center justify-between text-xs text-neutral-400">
              <span className="flex items-center gap-1.5">
                <Award className="w-3.5 h-3.5 text-amber-400" />
                Table Leader
              </span>
              <span className="text-xs font-mono font-bold text-amber-400">1st</span>
            </div>
            <div className="text-base font-bold text-white truncate">
              {leader ? leader.team.name : 'Manchester City'}
            </div>
            <div className="text-[11px] text-neutral-400">
              {leader ? `${leader.points} pts • ${leader.played} played` : ''}
            </div>
          </div>

          {/* Tile 2: Table Movers */}
          <div className="bg-neutral-950/50 border border-neutral-800/60 rounded-xl p-3.5 space-y-1">
            <div className="flex items-center justify-between text-xs text-neutral-400">
              <span className="flex items-center gap-1.5">
                <TrendingUp className="w-3.5 h-3.5 text-emerald-400" />
                Table Shift
              </span>
              {biggestMoverUp && (
                <span className="flex items-center text-xs font-bold text-emerald-400">
                  <ArrowUpRight className="w-3.5 h-3.5" />
                  +{biggestMoverUp.change}
                </span>
              )}
            </div>
            <div className="text-base font-bold text-white truncate">
              {biggestMoverUp ? `${biggestMoverUp.team.name}` : 'No changes'}
            </div>
            <div className="text-[11px] text-neutral-400">
              {biggestMoverDown 
                ? `Biggest drop: ${biggestMoverDown.team.name} (${biggestMoverDown.change})`
                : 'Steady table'}
            </div>
          </div>

          {/* Tile 3: Top Performer */}
          <div className="bg-neutral-950/50 border border-neutral-800/60 rounded-xl p-3.5 space-y-1">
            <div className="flex items-center justify-between text-xs text-neutral-400">
              <span className="flex items-center gap-1.5">
                <Flame className="w-3.5 h-3.5 text-orange-400" />
                Gameweek MVP
              </span>
              {topPerformer && (
                <span className="text-xs font-bold text-orange-400">
                  {topPerformer.points} pts
                </span>
              )}
            </div>
            <div className="text-base font-bold text-white truncate">
              {topPerformer ? `${topPerformer.playerName} (${topPerformer.teamShortName})` : 'N/A'}
            </div>
            <div className="text-[11px] text-neutral-400 truncate">
              {topPerformer ? topPerformer.highlightTags.join(' • ') : ''}
            </div>
          </div>

          {/* Tile 4: Injury Intel */}
          <div className="bg-neutral-950/50 border border-neutral-800/60 rounded-xl p-3.5 space-y-1">
            <div className="flex items-center justify-between text-xs text-neutral-400">
              <span className="flex items-center gap-1.5">
                <ShieldAlert className="w-3.5 h-3.5 text-rose-400" />
                Star News & Doubts
              </span>
              <span className="text-xs font-bold text-rose-400">
                {starInjuriesCount} Alerts
              </span>
            </div>
            <div className="text-base font-bold text-white truncate">
              Medical Bulletins
            </div>
            <div className="text-[11px] text-neutral-400">
              Key players sidelined or doubtful
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { PlayerNewsItem, FavoritesState } from '@/types';
import { ShieldAlert, Star, Search, AlertCircle, Heart, XCircle, Clock } from 'lucide-react';

interface PlayerNewsViewProps {
  newsItems: PlayerNewsItem[];
  favorites: FavoritesState;
  onOpenFavorites: () => void;
  myFeedOnly: boolean;
}

export function PlayerNewsView({
  newsItems,
  favorites,
  onOpenFavorites,
  myFeedOnly,
}: PlayerNewsViewProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [onlyStars, setOnlyStars] = useState(false);
  const [severityFilter, setSeverityFilter] = useState<'all' | 'high' | 'medium'>('all');

  const filteredNews = newsItems.filter(item => {
    // Search
    const matchesSearch =
      item.playerName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.teamName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.news.toLowerCase().includes(searchTerm.toLowerCase());
    if (!matchesSearch) return false;

    // Star filter
    if (onlyStars && !item.isStarPlayer) return false;

    // Severity filter
    if (severityFilter !== 'all' && item.severity !== severityFilter) return false;

    // My feed only
    if (myFeedOnly) {
      const isFavPlayer = favorites.playerIds.includes(item.playerId);
      // Also match if user's favorite team is this player's team
      const isFavTeam = favorites.teamIds.length > 0 && false; // playerIds prioritised
      if (favorites.playerIds.length > 0 && !isFavPlayer) return false;
    }

    return true;
  });

  return (
    <div className="space-y-4">
      {/* Header & Filter Controls */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-neutral-900/60 border border-neutral-800 rounded-xl p-4">
        <div>
          <h2 className="text-lg font-bold text-white flex items-center gap-2">
            <ShieldAlert className="w-5 h-5 text-rose-400" />
            Player News & Injury Intel
          </h2>
          <p className="text-xs text-neutral-400">
            Medical updates, fitness doubts, suspension notices, and availability percentage
          </p>
        </div>

        {/* Filter Toolbar */}
        <div className="flex flex-wrap items-center gap-2">
          {/* Search */}
          <div className="relative">
            <Search className="w-3.5 h-3.5 text-neutral-500 absolute left-3 top-1/2 -translate-y-1/2" />
            <input
              type="text"
              placeholder="Search injured players..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="bg-neutral-950 border border-neutral-800 rounded-xl pl-8 pr-3 py-1.5 text-xs text-white placeholder-neutral-500 focus:outline-none focus:border-neutral-600 w-44 sm:w-56"
            />
          </div>

          {/* Star Filter */}
          <button
            onClick={() => setOnlyStars(!onlyStars)}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold border transition ${
              onlyStars
                ? 'bg-amber-500/20 text-amber-300 border-amber-500/50'
                : 'bg-neutral-950 text-neutral-400 border-neutral-800 hover:text-white'
            }`}
          >
            <Star className="w-3.5 h-3.5 fill-current" />
            <span>Star Talismans</span>
          </button>

          {/* Severity selector */}
          <select
            value={severityFilter}
            onChange={(e) => setSeverityFilter(e.target.value as 'all' | 'high' | 'medium')}
            className="bg-neutral-950 border border-neutral-800 rounded-xl px-2.5 py-1.5 text-xs text-neutral-300 focus:outline-none focus:border-neutral-600"
          >
            <option value="all">All Severities</option>
            <option value="high">Ruled Out / Suspended</option>
            <option value="medium">Doubtful (25%-75%)</option>
          </select>
        </div>
      </div>

      {/* News Cards Grid */}
      {filteredNews.length === 0 ? (
        <div className="bg-neutral-900/40 border border-dashed border-neutral-800 rounded-2xl p-8 text-center space-y-3">
          <AlertCircle className="w-8 h-8 text-neutral-500 mx-auto" />
          <h3 className="text-base font-semibold text-white">No injury alerts matching criteria</h3>
          <p className="text-xs text-neutral-400 max-w-sm mx-auto">
            No news items found for current filters. Try relaxing search query or viewing all players.
          </p>
          <button
            onClick={onOpenFavorites}
            className="px-4 py-2 bg-neutral-800 hover:bg-neutral-700 text-amber-300 rounded-xl text-xs font-semibold transition"
          >
            Manage Tracked Players
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filteredNews.map((item) => {
            const isFavPlayer = favorites.playerIds.includes(item.playerId);

            let statusBg = 'bg-rose-500/15 text-rose-400 border-rose-500/30';
            let statusIcon = XCircle;
            let statusLabel = 'Ruled Out';

            if (item.status === 'suspended') {
              statusBg = 'bg-purple-500/15 text-purple-400 border-purple-500/30';
              statusIcon = ShieldAlert;
              statusLabel = 'Suspended';
            } else if (item.status === 'doubtful') {
              statusBg = 'bg-amber-500/15 text-amber-400 border-amber-500/30';
              statusIcon = Clock;
              statusLabel = item.chanceOfPlaying !== null ? `${item.chanceOfPlaying}% Doubt` : 'Doubtful';
            } else if (item.status === 'unavailable') {
              statusBg = 'bg-neutral-700/30 text-neutral-400 border-neutral-700';
              statusIcon = AlertCircle;
              statusLabel = 'Unavailable';
            }

            const StatusIconComponent = statusIcon;

            return (
              <div
                key={item.playerId}
                className={`relative flex flex-col justify-between overflow-hidden rounded-2xl bg-neutral-900/80 border p-5 transition-all ${
                  isFavPlayer
                    ? 'border-amber-500/50 shadow-lg shadow-amber-500/10 ring-1 ring-amber-500/30'
                    : 'border-neutral-800/80 hover:border-neutral-700'
                }`}
              >
                <div>
                  {/* Top Header */}
                  <div className="flex items-center justify-between gap-2 mb-3">
                    <div className="flex items-center gap-1.5">
                      <span className="px-2 py-0.5 rounded text-[10px] font-black uppercase tracking-wider bg-neutral-800 text-neutral-300">
                        {item.position}
                      </span>
                      <span className="text-xs font-bold text-neutral-400">
                        {item.teamName} ({item.teamShortName})
                      </span>
                    </div>

                    <div className="flex items-center gap-1.5">
                      {item.isStarPlayer && (
                        <span className="flex items-center gap-1 px-2 py-0.5 rounded-full bg-amber-500/15 border border-amber-500/30 text-amber-400 text-[10px] font-bold">
                          <Star className="w-3 h-3 fill-amber-400" />
                          Star Player
                        </span>
                      )}

                      {isFavPlayer && (
                        <Heart className="w-3.5 h-3.5 text-rose-400 fill-rose-400" />
                      )}
                    </div>
                  </div>

                  {/* Player Name & Status Tag */}
                  <div className="flex items-start justify-between gap-2 mb-3">
                    <h3 className="text-lg font-black text-white tracking-tight">
                      {item.playerName}
                    </h3>

                    <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-bold border ${statusBg}`}>
                      <StatusIconComponent className="w-3.5 h-3.5" />
                      {statusLabel}
                    </span>
                  </div>

                  {/* News Description */}
                  <p className="text-xs text-neutral-300 leading-relaxed bg-neutral-950/60 border border-neutral-800/80 rounded-xl p-3 mb-4">
                    {item.news}
                  </p>
                </div>

                {/* Chance of Playing Progress Bar */}
                {item.chanceOfPlaying !== null && (
                  <div className="space-y-1.5 pt-2 border-t border-neutral-800/60">
                    <div className="flex items-center justify-between text-[11px] text-neutral-400 font-medium">
                      <span>Playing Probability:</span>
                      <span className={item.chanceOfPlaying >= 75 ? 'text-amber-400 font-bold' : 'text-rose-400 font-bold'}>
                        {item.chanceOfPlaying}%
                      </span>
                    </div>
                    <div className="w-full h-1.5 bg-neutral-800 rounded-full overflow-hidden">
                      <div
                        className={`h-full rounded-full transition-all ${
                          item.chanceOfPlaying >= 75
                            ? 'bg-amber-400'
                            : item.chanceOfPlaying >= 25
                            ? 'bg-orange-500'
                            : 'bg-rose-500'
                        }`}
                        style={{ width: `${item.chanceOfPlaying}%` }}
                      />
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { PlayerPerformance, FavoritesState } from '@/types';
import { Flame, Star, Award, Heart, Sparkles } from 'lucide-react';

interface PlayerPerformancesViewProps {
  performances: PlayerPerformance[];
  favorites: FavoritesState;
  onOpenFavorites: () => void;
  myFeedOnly: boolean;
}

export function PlayerPerformancesView({
  performances,
  favorites,
  onOpenFavorites,
  myFeedOnly,
}: PlayerPerformancesViewProps) {
  const [selectedPos, setSelectedPos] = useState<string>('ALL');

  const filtered = performances.filter(p => {
    if (selectedPos !== 'ALL' && p.position !== selectedPos) return false;
    if (!myFeedOnly) return true;
    if (favorites.playerIds.length === 0) return true;
    return favorites.playerIds.includes(p.playerId);
  });

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 bg-neutral-900/60 border border-neutral-800 rounded-xl p-4">
        <div>
          <h2 className="text-lg font-bold text-white flex items-center gap-2">
            <Flame className="w-5 h-5 text-orange-400" />
            Standout Match Performances
          </h2>
          <p className="text-xs text-neutral-400">
            Gameweek MVPs, multi-goal heroes, creative playmakers, and defensive stalwarts
          </p>
        </div>

        {/* Position Filter Chips */}
        <div className="flex items-center gap-1 bg-neutral-950 p-1 rounded-xl border border-neutral-800 self-start sm:self-auto text-xs">
          {['ALL', 'FWD', 'MID', 'DEF', 'GKP'].map((pos) => (
            <button
              key={pos}
              onClick={() => setSelectedPos(pos)}
              className={`px-3 py-1.5 rounded-lg font-semibold transition ${
                selectedPos === pos
                  ? 'bg-neutral-800 text-white shadow-sm'
                  : 'text-neutral-400 hover:text-white'
              }`}
            >
              {pos}
            </button>
          ))}
        </div>
      </div>

      {/* Cards Grid */}
      {filtered.length === 0 ? (
        <div className="bg-neutral-900/40 border border-dashed border-neutral-800 rounded-2xl p-8 text-center space-y-3">
          <Heart className="w-8 h-8 text-rose-400/50 mx-auto" />
          <h3 className="text-base font-semibold text-white">No standout performances found for current filter</h3>
          <p className="text-xs text-neutral-400 max-w-sm mx-auto">
            None of your tracked players had standout metrics recorded this gameweek or match the position filter.
          </p>
          <button
            onClick={onOpenFavorites}
            className="px-4 py-2 bg-neutral-800 hover:bg-neutral-700 text-amber-300 rounded-xl text-xs font-semibold transition"
          >
            Manage Tracked Players
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filtered.map((perf, index) => {
            const isFavoritePlayer = favorites.playerIds.includes(perf.playerId);
            const isFavoriteTeam = favorites.teamIds.length > 0; // check if team is tracked
            const isGameweekTop = index === 0;

            return (
              <div
                key={perf.playerId}
                className={`relative flex flex-col justify-between overflow-hidden rounded-2xl bg-neutral-900/80 border p-5 transition-all ${
                  isFavoritePlayer
                    ? 'border-amber-500/50 shadow-lg shadow-amber-500/10 ring-1 ring-amber-500/40'
                    : isGameweekTop
                    ? 'border-orange-500/40 bg-gradient-to-b from-neutral-900 via-neutral-900/90 to-neutral-950 shadow-md'
                    : 'border-neutral-800/80 hover:border-neutral-700'
                }`}
              >
                {/* Top Badge Indicators */}
                <div className="flex items-center justify-between gap-2 mb-3">
                  <div className="flex items-center gap-1.5">
                    <span className="px-2 py-0.5 rounded-md text-[10px] font-black uppercase tracking-wider bg-neutral-800 text-neutral-300 border border-neutral-700">
                      {perf.position}
                    </span>
                    <span className="text-xs font-bold text-neutral-400">
                      {perf.teamName} ({perf.teamShortName})
                    </span>
                  </div>

                  {isFavoritePlayer && (
                    <div className="flex items-center gap-1 px-2 py-0.5 rounded-full bg-amber-500/15 border border-amber-500/30 text-amber-400 text-[10px] font-bold">
                      <Star className="w-3 h-3 fill-amber-400" />
                      Favorite
                    </div>
                  )}

                  {!isFavoritePlayer && isGameweekTop && (
                    <div className="flex items-center gap-1 px-2 py-0.5 rounded-full bg-orange-500/15 border border-orange-500/30 text-orange-400 text-[10px] font-bold">
                      <Sparkles className="w-3 h-3" />
                      GW Leader
                    </div>
                  )}
                </div>

                {/* Player Identity & Score */}
                <div className="flex items-start justify-between gap-3 mb-4">
                  <div>
                    <h3 className="text-lg font-black text-white tracking-tight flex items-center gap-1.5">
                      {perf.playerName}
                    </h3>
                    <p className="text-xs text-neutral-400">
                      {perf.fixtureSummary}
                    </p>
                  </div>

                  {/* Gameweek Points Bubble */}
                  <div className="flex flex-col items-center justify-center px-3 py-1.5 bg-gradient-to-b from-emerald-500/20 to-emerald-500/10 border border-emerald-500/30 rounded-xl shrink-0">
                    <span className="text-xl font-black text-emerald-400 leading-none">
                      {perf.points}
                    </span>
                    <span className="text-[9px] uppercase tracking-wider font-bold text-emerald-300/80 mt-0.5">
                      Points
                    </span>
                  </div>
                </div>

                {/* Performance Stat Metrics Grid */}
                <div className="grid grid-cols-4 gap-2 bg-neutral-950/60 border border-neutral-800/80 rounded-xl p-2.5 mb-3 text-center">
                  <div>
                    <div className="text-[10px] text-neutral-400 uppercase font-semibold">Goals</div>
                    <div className="text-sm font-bold text-white mt-0.5">{perf.goals}</div>
                  </div>
                  <div>
                    <div className="text-[10px] text-neutral-400 uppercase font-semibold">Assists</div>
                    <div className="text-sm font-bold text-white mt-0.5">{perf.assists}</div>
                  </div>
                  <div>
                    <div className="text-[10px] text-neutral-400 uppercase font-semibold">
                      {perf.position === 'GKP' ? 'Saves' : 'Clean Sh.'}
                    </div>
                    <div className="text-sm font-bold text-white mt-0.5">
                      {perf.position === 'GKP' ? perf.saves : (perf.cleanSheet ? 'Yes' : 'No')}
                    </div>
                  </div>
                  <div>
                    <div className="text-[10px] text-neutral-400 uppercase font-semibold">Bonus</div>
                    <div className="text-sm font-bold text-amber-400 mt-0.5">
                      {perf.bonus > 0 ? `+${perf.bonus}` : '0'}
                    </div>
                  </div>
                </div>

                {/* Highlight Tag Pills */}
                <div className="flex flex-wrap gap-1.5 pt-1">
                  {perf.highlightTags.map((tag, idx) => (
                    <span
                      key={idx}
                      className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full bg-neutral-800/80 border border-neutral-700/60 text-neutral-200 text-[11px] font-medium"
                    >
                      {tag}
                    </span>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { RundownData, FavoritesState } from '@/types';
import { Header } from '@/components/Header';
import { OverviewHero } from '@/components/OverviewHero';
import { MatchResultsView } from '@/components/MatchResultsView';
import { PlayerPerformancesView } from '@/components/PlayerPerformancesView';
import { LeagueTableView } from '@/components/LeagueTableView';
import { PlayerNewsView } from '@/components/PlayerNewsView';
import { FavoritesModal } from '@/components/FavoritesModal';

const FAVORITES_STORAGE_KEY = 'epl_digest_favorites_v1';

interface RundownDashboardProps {
  initialData: RundownData;
}

export function RundownDashboard({ initialData }: RundownDashboardProps) {
  const [data, setData] = useState<RundownData>(initialData);
  const [favorites, setFavorites] = useState<FavoritesState>({
    teamIds: [1, 15], // Default starter: Arsenal and Man City
    playerIds: [411, 101, 115], // Default starter: Haaland, Henderson, De Cuyper
  });
  const [isFavoritesOpen, setIsFavoritesOpen] = useState(false);
  const [myFeedOnly, setMyFeedOnly] = useState(false);
  const [activeTab, setActiveTab] = useState<'all' | 'matches' | 'performers' | 'table' | 'news'>('all');
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [lastRefreshedText, setLastRefreshedText] = useState('Just now');

  // Load favorites from localStorage on client mount
  useEffect(() => {
    try {
      const stored = localStorage.getItem(FAVORITES_STORAGE_KEY);
      if (stored) {
        const parsed = JSON.parse(stored);
        if (Array.isArray(parsed.teamIds) && Array.isArray(parsed.playerIds)) {
          setFavorites(parsed);
        }
      }
    } catch (e) {
      console.warn('Failed to parse stored favorites', e);
    }
  }, []);

  const handleUpdateFavorites = (newFavorites: FavoritesState) => {
    setFavorites(newFavorites);
    try {
      localStorage.setItem(FAVORITES_STORAGE_KEY, JSON.stringify(newFavorites));
    } catch (e) {
      console.warn('Failed to save favorites to localStorage', e);
    }
  };

  const handleRefresh = async () => {
    setIsRefreshing(true);
    try {
      const res = await fetch('/api/rundown');
      if (res.ok) {
        const updatedData = await res.json();
        setData(updatedData);
        setLastRefreshedText(new Date().toLocaleTimeString());
      }
    } catch (err) {
      console.error('Failed to refresh data', err);
    } finally {
      setIsRefreshing(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#0a0a0c] text-neutral-100 flex flex-col font-sans selection:bg-emerald-500/30 selection:text-emerald-200">
      {/* Sticky Header Navigation */}
      <Header
        currentGameweek={data.currentGameweek}
        season={data.season}
        favorites={favorites}
        onOpenFavorites={() => setIsFavoritesOpen(true)}
        myFeedOnly={myFeedOnly}
        onToggleMyFeed={() => setMyFeedOnly(!myFeedOnly)}
        onRefresh={handleRefresh}
        isRefreshing={isRefreshing}
        activeTab={activeTab}
        onChangeTab={setActiveTab}
      />

      {/* Main Container */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-8">
        {/* Overview Hero Summary Banner */}
        <OverviewHero
          data={data}
          favorites={favorites}
          onOpenFavorites={() => setIsFavoritesOpen(true)}
          myFeedOnly={myFeedOnly}
        />

        {/* View Switcher Container */}
        {activeTab === 'all' && (
          <div className="space-y-10">
            {/* 1. Impressive Player Performances */}
            <section>
              <PlayerPerformancesView
                performances={data.topPerformers}
                favorites={favorites}
                onOpenFavorites={() => setIsFavoritesOpen(true)}
                myFeedOnly={myFeedOnly}
              />
            </section>

            {/* 2. Match Results & Upcoming Fixtures */}
            <section>
              <MatchResultsView
                recentMatches={data.recentMatches}
                upcomingMatches={data.upcomingMatches}
                favorites={favorites}
                onOpenFavorites={() => setIsFavoritesOpen(true)}
                myFeedOnly={myFeedOnly}
              />
            </section>

            {/* 3. League Table & Position Movers */}
            <section>
              <LeagueTableView
                table={data.table}
                favorites={favorites}
                onOpenFavorites={() => setIsFavoritesOpen(true)}
                myFeedOnly={myFeedOnly}
              />
            </section>

            {/* 4. Player News & Injury Bulletins */}
            <section>
              <PlayerNewsView
                newsItems={data.injuryNews}
                favorites={favorites}
                onOpenFavorites={() => setIsFavoritesOpen(true)}
                myFeedOnly={myFeedOnly}
              />
            </section>
          </div>
        )}

        {activeTab === 'matches' && (
          <section>
            <MatchResultsView
              recentMatches={data.recentMatches}
              upcomingMatches={data.upcomingMatches}
              favorites={favorites}
              onOpenFavorites={() => setIsFavoritesOpen(true)}
              myFeedOnly={myFeedOnly}
            />
          </section>
        )}

        {activeTab === 'performers' && (
          <section>
            <PlayerPerformancesView
              performances={data.topPerformers}
              favorites={favorites}
              onOpenFavorites={() => setIsFavoritesOpen(true)}
              myFeedOnly={myFeedOnly}
            />
          </section>
        )}

        {activeTab === 'table' && (
          <section>
            <LeagueTableView
              table={data.table}
              favorites={favorites}
              onOpenFavorites={() => setIsFavoritesOpen(true)}
              myFeedOnly={myFeedOnly}
            />
          </section>
        )}

        {activeTab === 'news' && (
          <section>
            <PlayerNewsView
              newsItems={data.injuryNews}
              favorites={favorites}
              onOpenFavorites={() => setIsFavoritesOpen(true)}
              myFeedOnly={myFeedOnly}
            />
          </section>
        )}
      </main>

      {/* Footer */}
      <footer className="border-t border-neutral-900 bg-neutral-950/80 py-8 px-4 text-center text-xs text-neutral-500">
        <div className="max-w-7xl mx-auto flex flex-col sm:flex-row items-center justify-between gap-4">
          <div>
            <span className="font-bold text-neutral-300">EPL Digest</span> • Premier League matchday intelligence & news.
          </div>
          <div className="flex items-center gap-4 text-neutral-400">
            <span>Last synchronized: {lastRefreshedText}</span>
            <span>•</span>
            <span>Free Premier League & FPL Public Datasets</span>
          </div>
        </div>
      </footer>

      {/* Favorites Selector Modal */}
      <FavoritesModal
        isOpen={isFavoritesOpen}
        onClose={() => setIsFavoritesOpen(false)}
        allTeams={data.allTeams}
        allPlayers={data.allPlayers}
        favorites={favorites}
        onUpdateFavorites={handleUpdateFavorites}
      />
    </div>
  );
}
